"""Build a static, source-led report and local agency-use workbook."""
import json,html,re
from pathlib import Path
from use_content import STEPS,REVIEW
R=Path(__file__).resolve().parents[1];S=R/'site/proposed-fedramp-use';D=R/'data/proposed-fedramp-use'
S.mkdir(exist_ok=True)
Q={q['id']:q for q in json.loads((D/'quotations.json').read_text())};sources={s['id']:s for s in json.loads((D/'sources.json').read_text())};used=[]
def e(x):return html.escape(str(x),quote=True)
def quote(id):
 q=Q[id];s=sources[q['source_id']];used.append(id)
 label={'Law':'law','OMB policy':'omb','Mandatory standard':'standard'}.get(s['kind'],'guidance')
 link=s['local']+('#page='+str(q['pages'][0]) if q['pages'] else '')
 # Keep all wording. Paragraph breaks only make clauses easier to compare.
 t=e(q['text']);t=re.sub(r' (‘‘\([A-Za-z0-9]+\))',r'<br>\1',t)
 t=re.sub(r' ([a-i]\. )',r'<br>\1',t) if id in ['sa9-control','sa4-contract','ca3-exchange'] else t
 return f'<figure class="quotation {label}" id="quote-{id}"><div class="authority-label">{e(s["kind"])}</div><blockquote><p>{t}</p></blockquote><figcaption><a href="#source-{s["id"]}">{e(s["title"])}</a> · {e(s["date"])}<br>{e(q["locator"])} · <a href="{e(link)}">Read original'+(f' · PDF p. {q["pages"][0]}' if q['pages'] else '')+'</a></figcaption></figure>'
def concern(title,body):return f'<aside class="concern"><strong>Point of concern · {e(title)}</strong><p>{e(body)}</p></aside>'
sections=[('premise','The premise'),('review','Review of six steps'),('authority','What the law permits')]+[(s['id'],str(i+1)+'. '+s['title']) for i,s in enumerate(STEPS)]+[('record','Decision record'),('sources','Sources and editions')]
nav=''.join(f'<a href="#{id}">{e(title)}</a>' for id,title in sections)
p=['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A proposed agency cloud-use workflow, reviewed against FISMA, the FedRAMP Act, OMB policy, and NIST. Includes primary quotations and an editable local workbook."><title>Proposed FedRAMP use · A-130 research</title><link rel="stylesheet" href="report.css"><script src="workbook.js" defer></script></head><body><a class="skip" href="#main">Skip to report</a><aside class="rail"><a class="wordmark" href="../index.html">A–130<span>History & authority</span></a><details class="contents" open><summary>On this page</summary><nav aria-label="Page sections">'+nav+'</nav></details><div class="site-links"><a href="../on-behalf/index.html">Information and systems history</a><a href="../law/index.html">Read the law</a><a href="https://github.com/pete-wai/fedramp-a130">Repository</a></div></aside><main id="main"><header><p class="eyebrow">Proposal & working paper · 26 October 2026</p><h1>Using cloud services through FedRAMP</h1><p class="deck">Reuse the service assessment. Authorize the agency’s use. Keep responsibility for the whole system.</p><p>This report reviews a proposed agency workflow and turns it into an eight-step workbook. It is an independent analysis, not official FedRAMP guidance or an authorization.</p><div class="jump-links"><a href="#review">Review the six proposed steps</a><a href="#workbook">Start the workbook ↓</a></div></header>']
p+=['<section id="premise" class="reading"><h2>The core premise</h2><p class="lead">FedRAMP can standardize assurance about an external cloud service. The agency still defines its information and mission needs, implements its part of the protections, and accepts the risk of using that service.</p><p>That is a defensible approach under the FedRAMP Act, M-24-15, and NIST’s external-service model. It does not create two separate legal regimes. FedRAMP operates within the federal information-security framework; agency monitoring must use service evidence to support the agency’s own risk decisions.</p><p><strong>The main correction:</strong> SA-9 tells an agency how to govern external system services. It does not establish a new authorization category. A “Cloud Service Authorization” could be a useful service-use record, but its effect and relationship to the agency ATO or ATU must be defined.</p><p>The current FedRAMP agency-use pages already describe much of this approach. Their text is quoted here as published program guidance, alongside the underlying law and policy.</p>',quote('fed-premise'),'<div class="responsibilities" role="group" aria-label="Connected responsibilities"><article><span class="authority-label">FedRAMP & provider</span><h3>Assurance about the offering</h3><p>Assessment evidence, certification boundary, provider responsibilities, secure configuration guidance, findings, and ongoing service evidence.</p></article><div class="connection">Evidence informs the agency decision<br>Agency concerns feed back to FedRAMP</div><article><span class="authority-label">Agency</span><h3>Risk of the actual use</h3><p>Information, mission, system boundary, customer controls, integrations, agreements, authorization, and continued use or exit.</p></article></div><p class="caption">This is a responsibility map, not a legal boundary excluding the provider from applicable requirements. See SA-9 in steps 3 and 8, and M-24-15 in steps 7 and 8.</p>',concern('Commercial does not automatically mean outside federal system scope','The workflow does not depend on a blanket claim that commercial cloud services cannot operate on the government’s behalf. “External” in SA-9 concerns control implementation and assessment. FISMA, A-130, and FedRAMP have their own wording and scope. Record the facts and applicable responsibilities instead of using the service’s commercial status as an exemption.'),'</section>']
p+=['<section id="review" class="reading"><h2>Review of the six proposed steps</h2><p>The overall sequence works with three changes: add preparation and agreements, place final authorization after assessment, and connect the two monitoring streams.</p><ol class="review-list">']
for n,title,body,target in REVIEW:p+=[f'<li><h3>{e(title)}</h3><p>{e(body)} <a href="#{target}">See workbook step</a></p></li>']
p+=['</ol></section><section id="authority" class="reading"><h2>What the law lets FedRAMP standardize</h2><p>The 2022 Act gives GSA a program and process mandate. M-24-15 replaces the 2011 FedRAMP memorandum and assigns FedRAMP the process and criteria for a FedRAMP authorization. Those authorities support a reusable service-assurance process, templates, boundary guidance, and monitoring procedures.</p>',quote('act22-program'),quote('act-process'),quote('omb-rescind'),quote('omb-process'),'<h3>What those changes preserve</h3><p>The Act expressly preserves agency FISMA responsibility in §3613(e)(2), quoted in step 4. M-24-15 footnote 7 preserves other information-management, records, privacy, and cybersecurity obligations, quoted in step 7. Neither source supplies a blanket repeal of A-130 or NIST. The Act also requires consistency with NIST standards and guidelines and relevant statutes.</p>',quote('f14-program'),quote('rmf18-external'),concern('Apply newer reuse rules to older NIST procedures','SP 800-37 Rev. 2 Appendix F allows requests for additional controls or information when evaluating a shared service. For FedRAMP use, that older general procedure must be read with the later statutory presumption of adequacy, demonstrable-need provision, M-24-15, and current FedRAMP notification rules. Older discretion is not permission to duplicate the provider assessment.'),'<h3>Three decisions to keep distinct</h3><dl class="decisions"><dt>FedRAMP authorization / certification</dt><dd>The program’s determination about an offering. The Act and M-24-15 use “authorization”; the current 2026 program pages use “certification.” Preserve those terms in citations and identify the specific package/status being reused.</dd><dt>Proposed service-use record</dt><dd>An agency record of fit, responsibilities, evidence, conditions, and risk. This report proposes it as part of the agency authorization package. It does not create a new government-wide approval.</dd><dt>Agency ATO / ATU</dt><dd>The accountable official’s agency decision. The route and prerequisites matter. NIST’s ATU is a reuse mechanism, not a synonym for any SA-9 review. Current FedRAMP guidance emphasizes authorizing the agency system and its use of the service.</dd></dl>',quote('fed-before'),'</section>']
p+=['<section id="workbook"><h2>Agency-use workbook</h2><p>Use one worksheet per agency use and service; link related records when a system uses several services. Work through the eight records below. Steps 2–5 are iterative: evidence or design changes can send you back. Do not begin operational use until the required authorization is complete.</p><p>Use references to agency records. This page is a working aid, not the official repository. Answers stay in this browser session unless you choose browser storage or export them. Nothing entered here is sent to a server.</p><div id="workbook-tools" hidden><div class="tool-row"><button type="button" id="reading-toggle" aria-pressed="false">Show workbook only</button><button type="button" id="export-json">Export answers · JSON</button><button type="button" id="export-md">Export record · Markdown</button><button type="button" id="print">Print report & answers</button></div><div class="tool-row"><label class="import-label">Import answers <input id="import-json" type="file" accept="application/json,.json"></label><label class="save-label"><input type="checkbox" id="save-local"> Keep answers in this browser</label><button type="button" id="clear">Clear answers</button></div><p id="workbook-status" role="status" aria-live="polite">Session only. Export a copy before closing this page.</p><p class="small">JSON import replaces this worksheet after validation. Browser storage is specific to this site and browser. Exported files are your responsibility to store appropriately. Field completion does not mean approval.</p></div><noscript><p>JavaScript is off. Read all evidence and use the prompts below as a printable worksheet. Export and browser saving require JavaScript.</p></noscript></section><form id="worksheet" autocomplete="off">']
fields=[]
for i,s in enumerate(STEPS):
 p+=[f'<section class="step" id="{s["id"]}"><div class="step-heading"><span class="step-number">{i+1:02}</span><div><p class="eyebrow">RMF · {e(s["rmf"])}</p><h2>{e(s["title"])}</h2></div></div><p class="owner">Responsible participants: {e(s["owner"])}</p><div class="reading"><p class="lead">{e(s["summary"])}</p><p class="proposal-link">{e(s["original"])}</p><h3>What the agency does</h3><ul class="actions">'+''.join('<li>'+e(a)+'</li>' for a in s['actions'])+'</ul><h3>Why this fits</h3><p>'+e(s['alignment'])+'</p>',concern(*s['concern']),'<h3>Supporting language</h3>']
 p += [quote(id) for id in s['quotes']]
 p += ['</div><fieldset><legend>Record '+str(i+1)+' · '+e(s['title'])+'</legend>']
 for id,label,hint in s['fields']:
  fields.append(dict(id=id,label=label,step=i+1,title=s['title'],hint=hint))
  p += [f'<div class="field"><label for="field-{id}">{e(label)}</label><p id="hint-{id}" class="hint">{e(hint)}</p><textarea id="field-{id}" name="{id}" rows="4" maxlength="20000" aria-describedby="hint-{id}"></textarea><div class="print-answer" data-answer="{id}">Not recorded.</div></div>']
 p+=['</fieldset><a class="back-top" href="#workbook">Workbook tools ↑</a></section>']
p+=['</form><section id="record"><h2>What the completed record should show</h2><p>The authorizing official should be able to trace the decision from the agency’s information and mission to the selected service, evidence, customer responsibilities, assessment results, conditions, and ongoing monitoring. An exported worksheet helps assemble that record; it is not a signed authorization.</p><ul><li><strong>Scope:</strong> the actual agency use, information, system boundary, and provider offering.</li><li><strong>Protection:</strong> categorization, selected controls, allocation, agreements, and verified implementation.</li><li><strong>Evidence:</strong> FedRAMP material reused, agency assessment, unresolved issues, and justified additions.</li><li><strong>Decision:</strong> the authorized official, accepted risk, conditions, decision date, and required submission.</li><li><strong>Continued use:</strong> monitoring owners, evidence cadence, escalation, change triggers, and exit arrangements.</li></ul><p><a href="#workbook">Return to workbook controls</a></p></section><section id="sources" class="reading"><h2>Sources, editions, and limits</h2><p>Quoted passages retain the source wording. PDF line wrapping and line-end hyphenation are normalized; paragraph breaks are added for readability. Locators identify the printed section and original PDF page. The analysis and workbook prompts are this report’s interpretation and proposal.</p><p><strong>Currency:</strong> reviewed October 26, 2026. The statutory quotations come from the 2014 and 2022 enacted laws, checked against the site’s retained current-law collection (OLRC release 119-118, through September 30, 2026). This is not a claim to have audited every later enactment. A-130 is the 2016 revision; M-24-15 is July 25, 2024. SP 800-37 Rev. 2 is December 2018. The SP 800-53 Rev. 5 quotes use the December 2020 update; NIST’s August 2025 Release 5.2.0 changes do not alter SA-9 or the SA-4 control statement quoted here. Current baselines are in SP 800-53B and its applicable updates.</p><p><strong>Program guidance:</strong> the five current FedRAMP pages were captured October 26, 2026. The Agency Use page labels its rules required, with July 4, 2026 applicability dates. The local FedRAMP MCP snapshot was older and marked some rules as placeholders; the published page is the basis for the program-status descriptions here. See the <a href="https://www.fedramp.gov/2026/scope/">current scope guidance</a> for detailed exclusions and examples. National-security and classified systems are outside this workbook’s scope.</p><p>See the <a href="../on-behalf/index.html">information and systems history</a> for the earlier law, comments, and changes. This page concentrates on the proposed implementation. <a href="quotations.json" download>Download quotations</a> · <a href="sources.json" download>Download source metadata</a></p>']
for s in sources.values():
 p += [f'<article class="source" id="source-{s["id"]}"><h3>{e(s["title"])}</h3><p class="source-meta">{e(s["kind"])} · {e(s["date"])}</p><p><a href="{e(s["url"])}">Official source</a> · <a href="{e(s["local"])}" download>Retained original</a></p><details><summary>Edition and integrity</summary><p>{e(s.get("provenance","Official published page captured October 26, 2026. The accompanying text file is extracted from its article body."))}</p><p>SHA-256</p><code>{e(s["sha256"])}</code></details></article>']
p+=['</section><footer><p>Independent A-130 research · <a href="../index.html">History & authority</a> · <a href="#main">Back to top ↑</a></p></footer></main></body></html>']
S.joinpath('index.html').write_text('\n'.join(p))
# Only ship evidence actually used in this page; the selection file also retains unused candidates.
S.joinpath('quotations.json').write_text(json.dumps([Q[id] for id in used],indent=2,ensure_ascii=False)+'\n')
S.joinpath('sources.json').write_text(json.dumps(list(sources.values()),indent=2,ensure_ascii=False)+'\n')
S.joinpath('fields.json').write_text(json.dumps(fields,indent=2,ensure_ascii=False)+'\n')
print('Built proposed FedRAMP use:',len(STEPS),'steps,',len(used),'quotes,',len(fields),'fields')
